import sys
from collections import deque

def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    n = int(input[idx])
    idx += 1
    m = int(input[idx])
    idx += 1
    k = int(input[idx])
    idx += 1
    grid = []
    for _ in range(n):
        row = list(map(int, input[idx:idx + m]))
        idx += m
        grid.append(row)
    q = int(input[idx])
    idx += 1
    queries = []
    for _ in range(q):
        r1 = int(input[idx]) - 1
        idx += 1
        c1 = int(input[idx]) - 1
        idx += 1
        r2 = int(input[idx]) - 1
        idx += 1
    c2 = int(input[idx]) - 1
        idx += 1
    queries.append((r1, c1, r2, c2))
    color_positions = {i: [] for i in range(1, k + 1)}
    for i in range(n):
        for j in range(m):
            color_positions[grid[i][j]].append((i, j))
    distances = {}
    for color in range(1, k + 1):
        queue = deque(color_positions[color])
        visited = [[False] * m for _ in range(n)]
        for i, j in color_positions[color]:
            visited[i][j] = True
        dist = 0
        while queue:
            for _ in range(len(queue)):
                x, y = queue.popleft()
                if (x, y) not in distances:
                    distances[(x, y)] = dist
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny]:
                        visited[nx][ny] = True
                        queue.append((nx, ny))
            dist += 1
    results = []
    for r1, c1, r2, c2 in queries:
        if (r1, c1) == (r2, c2):
            results.append(0)
            continue
        min_dist = float('inf')
        for color in range(1, k + 1):
            if (r1, c1) in distances and (r2, c2) in distances:
                min_dist = min(min_dist, distances[(r1, c1)] + distances[(r2, c2)])
        for x1, y1 in color_positions[grid[r1][c1]]:
            for x2, y2 in color_positions[grid[r2][c2]]:
                min_dist = min(min_dist, abs(x1 - x2) + abs(y1 - y2))
        results.append(min_dist)
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
